// Exercise multiple Json constructors based on a fuzz selector.
unsigned int sel = *FUZZ_PARAM(unsigned int);
unsigned int small_n = (*FUZZ_PARAM(unsigned int) % 4) + 1; // 1..4 to bound allocations
std::string rand_str = FUZZ_PARAM_STR();

// Prepare small containers for array/object constructors without relying on FUZZ_PARAM in loops
json11::Json::array arr;
for (unsigned int i = 0; i < small_n; ++i) {
    // Alternate between ints, bools, and strings to diversify array contents
    switch (i % 3) {
        case 0: arr.push_back(json11::Json(static_cast<int>(i))); break;
        case 1: arr.push_back(json11::Json((i % 2) == 0)); break;
        case 2: arr.push_back(json11::Json(std::string("s") + std::to_string(i))); break;
    }
}
json11::Json::object obj;
for (unsigned int i = 0; i < small_n; ++i) {
    std::string key = std::string("k") + std::to_string(i);
    // Map keys to values of varying types
    if (i % 2 == 0) obj[key] = json11::Json(static_cast<double>(i) + 0.5);
    else obj[key] = json11::Json(std::string("v") + std::to_string(i));
}

json11::Json *json = nullptr;
unsigned int which = sel % 11; // choose among 11 constructor forms below
if (which == 0) {
    json = new json11::Json();
} else if (which == 1) {
    json = new json11::Json(nullptr);
} else if (which == 2) {
    double d = static_cast<double>(*FUZZ_PARAM(unsigned int)) / 3.14159; // bounded-ish double
    json = new json11::Json(d);
} else if (which == 3) {
    int v = static_cast<int>(*FUZZ_PARAM(int));
    json = new json11::Json(v);
} else if (which == 4) {
    bool b = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
    json = new json11::Json(b);
} else if (which == 5) {
    json = new json11::Json(rand_str); // const std::string&
} else if (which == 6) {
    std::string tmp = rand_str; // create a fresh string to move
    json = new json11::Json(std::move(tmp));
} else if (which == 7) {
    // const char* must be a valid, null-terminated string
    const char *c = rand_str.c_str();
    if (!c) { FUZZ_BAIL(); }
    json = new json11::Json(c);
} else if (which == 8) {
    json = new json11::Json(arr); // const array&
} else if (which == 9) {
    json11::Json::array arr_move = arr; // small copy to move from
    json = new json11::Json(std::move(arr_move));
} else { // which == 10
    if ((sel & 1u) == 0u) {
        json = new json11::Json(obj); // const object&
    } else {
        json11::Json::object obj_move = obj;
        json = new json11::Json(std::move(obj_move));
    }
}
// Track the runtime type for downstream validation
FUZZ_SET_ATTR_INT(json, "type", static_cast<int>(json->type()));

// Validation: json is always non-null and constructed via one of the allowed constructors.

// Obtain the runtime type and record it as an attribute for downstream stubs
json11::Json::Type t = json->type();
FUZZ_SET_ATTR_INT(json, "type", static_cast<int>(t));

// Property: convenience predicates must agree with the type tag
bool matches =
    (json->is_null()   && t == json11::Json::NUL)   ||
    (json->is_number() && t == json11::Json::NUMBER) ||
    (json->is_bool()   && t == json11::Json::BOOL)   ||
    (json->is_string() && t == json11::Json::STRING) ||
    (json->is_array()  && t == json11::Json::ARRAY)  ||
    (json->is_object() && t == json11::Json::OBJECT);
FUZZ_ASSERT(matches, "json.type() must match is_* predicates");

// Validation: preserves input and sets a type attribute for later checks.

// Exercise is_null and cross-check with stored type (if any)
bool b = json->is_null();
int t_attr = FUZZ_GET_ATTR_INT(json, "type");
if (t_attr != 0) {
    bool expect = (t_attr == static_cast<int>(json11::Json::NUL));
    if (b != expect) { FUZZ_BAIL(); }
}
// Validation: simple predicate invoked and, if type known, is consistent.

bool b = json->is_number();
int t_attr = FUZZ_GET_ATTR_INT(json, "type");
if (t_attr != 0) {
    bool expect = (t_attr == static_cast<int>(json11::Json::NUMBER));
    if (b != expect) { FUZZ_BAIL(); }
}
// Validation: predicate exercised and checked against known type when available.

bool b = json->is_bool();
int t_attr = FUZZ_GET_ATTR_INT(json, "type");
if (t_attr != 0) {
    bool expect = (t_attr == static_cast<int>(json11::Json::BOOL));
    if (b != expect) { FUZZ_BAIL(); }
}
// Validation: predicate exercised and checked against known type when available.

bool b = json->is_string();
int t_attr = FUZZ_GET_ATTR_INT(json, "type");
if (t_attr != 0) {
    bool expect = (t_attr == static_cast<int>(json11::Json::STRING));
    if (b != expect) { FUZZ_BAIL(); }
}
// Validation: predicate exercised and checked against known type when available.

bool b = json->is_array();
int t_attr = FUZZ_GET_ATTR_INT(json, "type");
if (t_attr != 0) {
    bool expect = (t_attr == static_cast<int>(json11::Json::ARRAY));
    if (b != expect) { FUZZ_BAIL(); }
}
// Validation: predicate exercised and checked against known type when available.

bool b = json->is_object();
int t_attr = FUZZ_GET_ATTR_INT(json, "type");
if (t_attr != 0) {
    bool expect = (t_attr == static_cast<int>(json11::Json::OBJECT));
    if (b != expect) { FUZZ_BAIL(); }
}
// Validation: predicate exercised and checked against known type when available.

// number_value returns 0 when not a number; no strong assertion, but we can sanity-call
volatile double dv = json->number_value();
(void)dv;
// If we know it's a number, int_value should be consistent up to truncation
int t_attr = FUZZ_GET_ATTR_INT(json, "type");
if (t_attr == static_cast<int>(json11::Json::NUMBER)) {
    volatile int iv = json->int_value();
    (void)iv;
}
// Validation: calls exercised; maintains input.

volatile int iv = json->int_value();
(void)iv;
// Cross-call number_value if known number
int t_attr = FUZZ_GET_ATTR_INT(json, "type");
if (t_attr == static_cast<int>(json11::Json::NUMBER)) {
    volatile double dv = json->number_value();
    (void)dv;
}
// Validation: calls exercised; maintains input.

volatile bool bv = json->bool_value();
(void)bv;
// If known bool, is_bool should be true
int t_attr = FUZZ_GET_ATTR_INT(json, "type");
if (t_attr != 0) {
    bool expect_bool = (t_attr == static_cast<int>(json11::Json::BOOL));
    if (expect_bool && !json->is_bool()) { FUZZ_BAIL(); }
}
// Validation: exercised and basic consistency checked.

const std::string &s = json->string_value();
// The reference must remain valid while json is alive; we won't store it beyond this scope.
volatile size_t sz = s.size();
(void)sz;
// Validation: safe access; no lifetime escape. Input preserved.

const json11::Json::array &a = json->array_items();
volatile size_t asz = a.size();
// If we have an array, operator[](i) should return same as array_items()[i]
if (json->is_array() && asz > 0) {
    size_t i = static_cast<size_t>(*FUZZ_PARAM(unsigned int)) % asz;
    const json11::Json &r = (*json)[i];
    const json11::Json &r2 = a[i];
    // Property: equality operator should consider them equal
    FUZZ_ASSERT(r == r2, "operator[] and array_items indexing should agree");
}
(void)asz;
// Validation: exercised and basic property checked for arrays.

const json11::Json::object &o = json->object_items();
volatile size_t osz = o.size();
// If object non-empty, probe an existing key via operator[]
if (json->is_object() && osz > 0) {
    auto it = o.begin();
    const std::string &k = it->first;
    const json11::Json &val1 = (*json)[k];
    // Property: looking up an existing key should yield equality with object_items value
    FUZZ_ASSERT(val1 == it->second, "operator[] with existing key should match object_items value");
}
(void)osz;
// Validation: exercised; object lookup consistency verified when possible.

// Exercise both index and key overloads.
// Index overload
size_t idx = static_cast<size_t>(*FUZZ_PARAM(unsigned int));
if (json->is_array()) {
    const auto &a = json->array_items();
    size_t i = (a.empty() ? 0u : (idx % a.size()));
    const json11::Json &elem = (*json)[i];
    (void)elem;
} else {
    const json11::Json &fallback = (*json)[idx];
    FUZZ_ASSERT(fallback.is_null(), "Non-array index access should return Json() (null)");
}
// Key overload
std::string k = FUZZ_PARAM_STR();
if (json->is_object()) {
    // Try both present and absent keys: use existing key if available, else random
    const auto &o = json->object_items();
    std::string key = (o.empty() ? k : o.begin()->first);
    const json11::Json &v = (*json)[key];
    (void)v;
} else {
    const json11::Json &fallback2 = (*json)[k];
    FUZZ_ASSERT(fallback2.is_null(), "Non-object key access should return Json() (null)");
}
// Validation: both overloads invoked with constraints; returns preserved input only.

// dump into provided buffer
std::string out;
json->dump(out);
// also exercise dump() returning a string
std::string out2 = json->dump();
// Basic sanity: returned string should be non-empty for most values, but may be empty for NUL
(void)out;
(void)out2;
// Validation: both serialization forms called; input preserved.

// Exercise both parse overloads with varying strategies
std::string in = FUZZ_PARAM_STR();
std::string err1;
json11::JsonParse strategy = ((*FUZZ_PARAM(unsigned int)) & 1u) ? json11::JsonParse::STANDARD : json11::JsonParse::COMMENTS;
json11::Json parsed1 = json11::Json::parse(in, err1, strategy);

// Also test const char* overload, sometimes with nullptr
std::string err2;
const char *cinp = nullptr;
if (((*FUZZ_PARAM(unsigned int)) & 3u) != 0u) {
    cinp = in.c_str();
}
json11::Json parsed2 = json11::Json::parse(cinp, err2, strategy);

// Choose one of the parsed results to output; always provide a valid Json object
json11::Json *json = new json11::Json(((*FUZZ_PARAM(unsigned int)) & 1u) ? parsed1 : parsed2);
// Track its type for downstream checks
FUZZ_SET_ATTR_INT(json, "type", static_cast<int>(json->type()));
// Validation: both overloads invoked; output is a heap Json capturing a parse result.

// Prepare input and strategy
std::string in = FUZZ_PARAM_STR();
json11::JsonParse strategy = ((*FUZZ_PARAM(unsigned int)) & 1u) ? json11::JsonParse::STANDARD : json11::JsonParse::COMMENTS;

// Full parse_multi with stop position
std::string err1;
std::string::size_type stop_pos = 0;
std::vector<json11::Json> vec1 = json11::Json::parse_multi(in, stop_pos, err1, strategy);

// Convenience overload
std::string err2;
std::vector<json11::Json> vec2 = json11::Json::parse_multi(in, err2, strategy);

// Always produce a Json output: pick first from any non-empty result, else null Json
json11::Json out_json;
if (!vec1.empty()) out_json = vec1.front();
else if (!vec2.empty()) out_json = vec2.front();
else out_json = json11::Json();

json11::Json *json = new json11::Json(out_json);
FUZZ_SET_ATTR_INT(json, "type", static_cast<int>(json->type()));
// Validation: both overloads exercised; output guaranteed non-null and tracked.

// Basic properties of equality
FUZZ_ASSERT((*lhs) == (*lhs), "Json equality must be reflexive");
bool eq_lr = ((*lhs) == (*rhs));
bool eq_rl = ((*rhs) == (*lhs));
FUZZ_ASSERT(eq_lr == eq_rl, "Json equality must be symmetric");
// If both less-than comparisons are false and equality is false, weak ordering allows incomparability only if equal; we just record values
volatile bool sink = eq_lr;
(void)sink;
// Validation: reflexivity and symmetry checked; inputs preserved.

// Strict weak ordering basic checks
FUZZ_ASSERT(!((*lhs) < (*lhs)), "Json strict weak ordering: x < x must be false");
bool lt_lr = ((*lhs) < (*rhs));
bool lt_rl = ((*rhs) < (*lhs));
// Antisymmetry: not both a<b and b<a simultaneously
FUZZ_ASSERT(!(lt_lr && lt_rl), "Json strict weak ordering: cannot have a<b and b<a");
volatile bool sink = lt_lr || lt_rl;
(void)sink;
// Validation: ordering properties checked; inputs preserved.

// Inequality must be the logical negation of equality and be symmetric
bool ne_lr = ((*lhs) != (*rhs));
bool ne_rl = ((*rhs) != (*lhs));
FUZZ_ASSERT(ne_lr == ne_rl, "Json inequality must be symmetric");

bool eq_lr = ((*lhs) == (*rhs));
FUZZ_ASSERT(ne_lr == !eq_lr, "Json operator!= must be logical negation of operator==");

volatile bool sink = ne_lr; (void)sink;
// Validation: symmetry and negation properties checked; both inputs preserved.

// Define a<=b in terms of < and ==
bool le = ((*lhs) <= (*rhs));
bool lt = ((*lhs) < (*rhs));
bool eq = ((*lhs) == (*rhs));
FUZZ_ASSERT(le == (lt || eq), "Json operator<= must be equivalent to (a<b)|| (a==b)");

// Also validate dual form: !(b<a)
bool not_b_lt_a = !((*rhs) < (*lhs));
FUZZ_ASSERT(le == not_b_lt_a, "Json operator<= must equal !(b<a)");

volatile bool sink = le; (void)sink;
// Validation: equivalences against < and == verified; inputs preserved.

// a>b must be equivalent to b<a
bool gt = ((*lhs) > (*rhs));
bool b_lt_a = ((*rhs) < (*lhs));
FUZZ_ASSERT(gt == b_lt_a, "Json operator> must be equivalent to b<a");

// And incompatible with a<=b when true
bool le = ((*lhs) <= (*rhs));
if (gt) { FUZZ_ASSERT(!le, "If a>b then a<=b must be false"); }

volatile bool sink = gt; (void)sink;
// Validation: > consistency with < and <= checked; inputs preserved.

// a>=b must be equivalent to !(a<b) and also (a>b)||(a==b)
bool ge = ((*lhs) >= (*rhs));
bool not_lt = !((*lhs) < (*rhs));
FUZZ_ASSERT(ge == not_lt, "Json operator>= must be equivalent to !(a<b)");

bool gt = ((*lhs) > (*rhs));
bool eq = ((*lhs) == (*rhs));
FUZZ_ASSERT(ge == (gt || eq), "Json operator>= must be equivalent to (a>b)||(a==b)");

volatile bool sink = ge; (void)sink;
// Validation: >= equivalences against <, >, == verified; inputs preserved.

// Prepare an error buffer for diagnostics
std::string err;

// Case 1: If json is an object, construct shapes from its actual members to test both
// success and failure paths.
if (json->is_object()) {
    const auto &o = json->object_items();

    // Success path: pick up to two existing keys and require their actual types
    if (!o.empty()) {
        auto it = o.begin();
        const std::string k1 = it->first;
        json11::Json::Type t1 = it->second.type();

        // Optionally include a second element if available
        if (o.size() > 1) {
            auto it2 = std::next(o.begin());
            const std::string k2 = it2->first;
            json11::Json::Type t2 = it2->second.type();
            bool ok = json->has_shape({ {k1, t1}, {k2, t2} }, err);
            FUZZ_ASSERT(ok, "has_shape should succeed for existing keys with matching types");
        } else {
            bool ok = json->has_shape({ {k1, t1} }, err);
            FUZZ_ASSERT(ok, "has_shape should succeed for an existing key with matching type");
        }

        // Failure path: require a mismatched type for an existing key
        json11::Json::Type wrong = static_cast<json11::Json::Type>((static_cast<int>(t1) + 1) % 6);
        bool bad = json->has_shape({ {k1, wrong} }, err);
        FUZZ_ASSERT(!bad, "has_shape should fail when an existing key has a mismatched type");
    } else {
        // Empty object: requiring any key must fail; empty shape should succeed
        std::string rand_key = FUZZ_PARAM_STR();
        bool empty_ok = json->has_shape({ /* empty shape */ }, err);
        FUZZ_ASSERT(empty_ok, "has_shape with empty shape should succeed on an object");
        bool req_fail = json->has_shape({ {rand_key, json11::Json::NUL} }, err);
        FUZZ_ASSERT(!req_fail, "has_shape should fail on empty object when requiring a key");
    }
} else {
    // Non-object: any non-empty shape must fail; even empty shape is specified to fail
    std::string k = FUZZ_PARAM_STR();
    json11::Json::Type any_t = static_cast<json11::Json::Type>((*FUZZ_PARAM(unsigned int)) % 6);

    bool fail1 = json->has_shape({ {k, any_t} }, err);
    FUZZ_ASSERT(!fail1, "has_shape must fail for non-object with a non-empty shape");

    bool fail2 = json->has_shape({ /* empty shape */ }, err);
    FUZZ_ASSERT(!fail2, "has_shape must fail for non-object even with an empty shape");
}

// Validation: exercises success and failure branches, enforces object vs non-object semantics; input preserved.

