import random
import json
import string
from typing import List, Tuple

# We generate valid JSON text buffers because the fuzzers frequently feed FUZZ_PARAM_STR
# into Json constructors and parsing-related code may be exercised elsewhere.
# Goals:
# - Produce a wide variety of valid JSON values (null, booleans, numbers, strings, arrays, objects).
# - Include objects with heterogeneous value types to exercise operator[] and has_shape paths.
# - Keep size <= 4096 bytes.
# - Deterministic given seed, but varied.
#
# We avoid malformed data; all outputs should be valid JSON under STANDARD mode.

_MAX_BYTES = 4096

def _rand(r: random.Random, lo: int, hi: int) -> int:
    return r.randint(lo, hi)

def _rand_bool(r: random.Random) -> bool:
    return bool(r.getrandbits(1))

def _rand_float(r: random.Random) -> float:
    # Generate diverse but finite floats
    # Mix of integers, small fractions, big magnitudes, and negatives
    choice = _rand(r, 0, 6)
    if choice == 0:
        return float(_rand(r, -1_000_000, 1_000_000))
    if choice == 1:
        return r.uniform(-1e9, 1e9)
    if choice == 2:
        return r.random()  # [0,1)
    if choice == 3:
        return -r.random()
    if choice == 4:
        # power of ten scale
        base = r.uniform(-1.0, 1.0)
        exp = _rand(r, -10, 10)
        return base * (10.0 ** exp)
    if choice == 5:
        # decimal-looking
        return round(r.uniform(-1e6, 1e6), _rand(r, 0, 8))
    return r.gauss(0.0, 1000.0)

def _rand_int(r: random.Random) -> int:
    # Range to fit in typical 32-bit int but also some boundaries
    opts = [0, 1, -1, 2**31 - 1, -2**31]
    if _rand_bool(r):
        return r.randint(-2**31, 2**31 - 1)
    return r.choice(opts)

def _rand_unicode_string(r: random.Random, min_len: int, max_len: int) -> str:
    length = _rand(r, min_len, max_len)
    # Make a blend of ASCII, escapes, and higher planes
    pieces: List[str] = []
    for _ in range(length):
        kind = _rand(r, 0, 9)
        if kind <= 4:
            pieces.append(r.choice(string.ascii_letters + string.digits + " _-:./@#"))
        elif kind == 5:
            pieces.append("\n")
        elif kind == 6:
            pieces.append("\t")
        elif kind == 7:
            # some unicode beyond ASCII
            cp = r.choice([
                0x00A9, 0x00AE, 0x03A9, 0x03C0, 0x20AC, 0x0416, 0x4E2D, 0x56FD, 0x1F600
            ])
            pieces.append(chr(cp))
        else:
            # quote/backslash to force escaping by json.dumps
            pieces.append(r.choice(['"', "\\"]))
    return "".join(pieces)

def _make_number(r: random.Random):
    if _rand_bool(r):
        return _rand_int(r)
    return _rand_float(r)

def _make_scalar(r: random.Random):
    t = _rand(r, 0, 4)
    if t == 0:
        return None
    if t == 1:
        return _rand_bool(r)
    if t == 2:
        return _make_number(r)
    if t == 3:
        # Strings can be empty or longish
        return _rand_unicode_string(r, 0, 64)
    # small array to diversify
    return [_make_scalar(r) for _ in range(_rand(r, 0, 3))]

def _make_array(r: random.Random, depth: int) -> list:
    n = _rand(r, 0, 6)
    arr = []
    for _ in range(n):
        arr.append(_make_value(r, depth + 1))
    return arr

def _make_object(r: random.Random, depth: int) -> dict:
    # Create keys that look like k0, k1 plus some random strings
    n = _rand(r, 0, 6)
    obj = {}
    fixed_first = min(n, 2)
    for i in range(fixed_first):
        key = f"k{i}"
        # choose value types to diversify has_shape cases
        vt = i % 3
        if vt == 0:
            val = _rand_int(r)
        elif vt == 1:
            val = _rand_bool(r)
        else:
            val = _rand_unicode_string(r, 1, 8)
        obj[key] = val
    for _ in range(n - fixed_first):
        # ensure unique keys; keep reasonably short keys
        key = _rand_unicode_string(r, 1, 10)
        # Clean potential duplicates by retrying a bit
        tries = 0
        while key in obj and tries < 3:
            key = _rand_unicode_string(r, 1, 10)
            tries += 1
        obj[key] = _make_value(r, depth + 1)
    return obj

def _make_value(r: random.Random, depth: int = 0):
    # Limit nesting to keep under size limits and avoid extreme depth
    if depth >= 4:
        # At deep levels prefer scalars and short arrays/objects
        choice = _rand(r, 0, 3)
    else:
        choice = _rand(r, 0, 5)
    if choice == 0:
        return None
    if choice == 1:
        return _rand_bool(r)
    if choice == 2:
        return _make_number(r)
    if choice == 3:
        return _rand_unicode_string(r, 0, 32)
    if choice == 4:
        return _make_array(r, depth)
    return _make_object(r, depth)

def _compose_multi_json(r: random.Random) -> str:
    # For parse_multi coverage, concatenate multiple JSON values separated by whitespace
    count = _rand(r, 1, 4)
    parts = []
    for _ in range(count):
        val = _make_value(r)
        parts.append(json.dumps(val, ensure_ascii=True, separators=(",", ":")))
    sep_choice = _rand(r, 0, 2)
    if sep_choice == 0:
        sep = " "
    elif sep_choice == 1:
        sep = "\n\t"
    else:
        sep = ""  # concatenated
    return sep.join(parts)

def _maybe_wrap_as_string(r: random.Random, s: str) -> str:
    # Sometimes provide plain JSON, sometimes embed as a JSON string value
    if _rand_bool(r):
        return s
    # wrap s as a JSON string (valid input for string constructors or parsing)
    return json.dumps(s, ensure_ascii=True)

def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Decide among primary shapes
    mode = _rand(r, 0, 6)
    if mode == 0:
        # Single rich object mixing arrays and scalars
        obj = {
            "k0": 0,
            "k1": True,
            "k2": "s0",
        }
        # Add random additional entries
        extra = _make_object(r, 0)
        obj.update(extra)
        payload = json.dumps(obj, ensure_ascii=True, separators=(",", ":"))
    elif mode == 1:
        # Array with mixed content to exercise index operator
        arr = []
        for i in range(_rand(r, 1, 8)):
            if i % 3 == 0:
                arr.append(_rand_int(r))
            elif i % 3 == 1:
                arr.append(_rand_bool(r))
            else:
                arr.append(f"s{i}")
        payload = json.dumps(arr, ensure_ascii=True, separators=(",", ":"))
    elif mode == 2:
        # Concatenated multiple JSON values for parse_multi
        payload = _compose_multi_json(r)
    elif mode == 3:
        # Pure scalar
        payload = json.dumps(_make_scalar(r), ensure_ascii=True)
    elif mode == 4:
        # Deeply nested but bounded
        value = _make_value(r, depth=0)
        payload = json.dumps(value, ensure_ascii=True, separators=(",", ":"))
    elif mode == 5:
        # Random string content as standalone (useful for string constructors)
        s = _rand_unicode_string(r, 0, 128)
        payload = _maybe_wrap_as_string(r, s)
    else:
        # Object tailored with alternating number/string to mirror stub's obj
        n = _rand(r, 1, 4)
        obj = {}
        for i in range(n):
            key = f"k{i}"
            if i % 2 == 0:
                obj[key] = float(i) + 0.5
            else:
                obj[key] = f"v{i}"
        payload = json.dumps(obj, ensure_ascii=True, separators=(",", ":"))

    # Ensure size constraint
    b = payload.encode("utf-8", errors="strict")
    if len(b) > _MAX_BYTES:
        # truncate gracefully; for JSON we try to keep it valid by falling back to a simple scalar
        simple = json.dumps(True)
        b = simple.encode("utf-8")
    return b

import random
import json
import string
from typing import Any, List, Dict, Tuple

# This generator produces valid JSON text buffers tailored to json11::Json::parse and parse_multi.
# Goals:
# - Produce a single JSON value (object/array/primitive) or multiple concatenated JSON values.
# - Include a variety of structures: nested arrays/objects, numbers (ints/floats), strings with escapes,
#   booleans, null, empty vs large containers.
# - Sometimes include C/C++/JSON-style comments (//, /* */) so the COMMENTS strategy has meaningful input
#   while still being acceptable JSON when comments are stripped.
# - Keep output <= 4096 bytes.

MAX_BYTES = 4096

PRIMITIVE_KEYS = [
    "id", "name", "title", "enabled", "count", "pi", "path", "created", "tags",
    "data", "nested", "empty", "value", "ok", "items", "meta", "config",
]

ESCAPE_CHARS = ["\\\"", "\\\\", "\\/", "\\b", "\\f", "\\n", "\\r", "\\t"]


def _rand_str(rng: random.Random, max_len: int = 40) -> str:
    # Mix alphanum, punctuation, unicode codepoints, and escape sequences
    length = rng.randint(0, max_len)
    pieces: List[str] = []
    for _ in range(length):
        choice = rng.random()
        if choice < 0.1:
            pieces.append(rng.choice(ESCAPE_CHARS))
        elif choice < 0.2:
            # Add a \uXXXX
            pieces.append("\\u%04X" % rng.randrange(0x0000, 0xD7FF))
        elif choice < 0.6:
            pieces.append(rng.choice(string.ascii_letters + string.digits + " _-.:,@"))
        else:
            # Some basic non-ascii
            cp = rng.choice([0x00E9, 0x03B1, 0x0416, 0x20AC, 0x2665])
            pieces.append(chr(cp))
    return "".join(pieces)


def _rand_number(rng: random.Random) -> Any:
    # Produce ints and floats, including edge-ish cases
    kind = rng.random()
    if kind < 0.45:
        return rng.randint(-2**31, 2**31 - 1)
    elif kind < 0.9:
        # floats with possible exponent
        base = rng.uniform(-1e6, 1e6)
        if rng.random() < 0.5:
            # quantize to produce .0 etc
            base = round(base, rng.randint(0, 8))
        return base
    else:
        # Special interesting magnitudes
        return rng.choice([0, 1, -1, 2**53 - 1, -(2**53 - 1), 1e-12, 1e12])


def _rand_bool_null(rng: random.Random) -> Any:
    return rng.choice([True, False, None])


def _rand_value(rng: random.Random, depth: int) -> Any:
    if depth <= 0:
        return rng.choice([
            _rand_number(rng), _rand_bool_null(rng), _rand_str(rng, 24)
        ])

    pick = rng.random()
    if pick < 0.2:
        return _rand_number(rng)
    elif pick < 0.35:
        return _rand_bool_null(rng)
    elif pick < 0.55:
        return _rand_str(rng, 60)
    elif pick < 0.8:
        return _rand_array(rng, depth - 1)
    else:
        return _rand_object(rng, depth - 1)


def _rand_array(rng: random.Random, depth: int) -> List[Any]:
    n = rng.randint(0, 8)
    return [_rand_value(rng, depth) for _ in range(n)]


def _rand_object(rng: random.Random, depth: int) -> Dict[str, Any]:
    n = rng.randint(0, 8)
    obj: Dict[str, Any] = {}
    for i in range(n):
        if rng.random() < 0.6:
            key = rng.choice(PRIMITIVE_KEYS)
        else:
            key = _rand_str(rng, 16)
        # ensure valid JSON key (avoid empty control-only strings)
        if not key:
            key = "key_%d" % i
        obj[key] = _rand_value(rng, depth - 1)
    # Add some known-pattern fields to trigger shape-like checks
    if rng.random() < 0.7:
        obj.setdefault("enabled", rng.choice([True, False]))
    if rng.random() < 0.7:
        obj.setdefault("count", rng.randint(0, 1000))
    if rng.random() < 0.5:
        obj.setdefault("items", _rand_array(rng, max(0, depth - 1)))
    return obj


def _to_json(v: Any) -> str:
    # json.dumps with ensure_ascii=False to preserve unicode, separators to make compact output
    return json.dumps(v, ensure_ascii=False, separators=(",", ":"))


def _with_comments(rng: random.Random, s: str) -> str:
    # Insert JS-style comments at safe boundaries: between values or around commas/braces.
    if not s:
        return s

    comment_snips = [
        "// single-line comment\n",
        "/* block comment */",
        "/*★multi★*/",
        "//☑\n",
    ]

    out: List[str] = []
    i = 0
    while i < len(s):
        ch = s[i]
        out.append(ch)
        # Only consider insertion near structural characters to avoid breaking strings
        if ch in ",[]{}:" and rng.random() < 0.25:
            out.append(comment_snips[rng.randrange(len(comment_snips))])
        i += 1

    # Optionally wrap whole document with a header/footer comment
    if rng.random() < 0.3:
        out.insert(0, comment_snips[rng.randrange(len(comment_snips))])
    if rng.random() < 0.3:
        out.append(comment_snips[rng.randrange(len(comment_snips))])

    return "".join(out)


def _multi_values(rng: random.Random) -> str:
    # Create multiple JSON values concatenated or separated by whitespace/comments
    parts: List[str] = []
    m = rng.randint(2, 6)
    for _ in range(m):
        depth = rng.randint(1, 4)
        val = _rand_value(rng, depth)
        js = _to_json(val)
        if rng.random() < 0.4:
            js = _with_comments(rng, js)
        parts.append(js)
        # whitespace separator variety
        if rng.random() < 0.8:
            parts.append("\n\t  ")
        # optional comment separator
        if rng.random() < 0.5:
            parts.append("// sep\n")
    return "".join(parts)


def _single_value(rng: random.Random) -> str:
    depth = rng.randint(1, 6)
    # Bias sometimes toward array/object roots for richer structure
    if rng.random() < 0.5:
        val: Any = _rand_object(rng, depth)
    elif rng.random() < 0.8:
        val = _rand_array(rng, depth)
    else:
        val = _rand_value(rng, depth)
    js = _to_json(val)
    if rng.random() < 0.5:
        js = _with_comments(rng, js)
    return js


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide between single JSON value and multi-value stream
    if rng.random() < 0.5:
        text = _single_value(rng)
    else:
        text = _multi_values(rng)

    # Ensure non-empty input sometimes for the const char* path, but allow occasional empty
    if rng.random() < 0.1:
        text = ""

    # Truncate to the maximum allowed size without breaking multibyte sequences
    b = text.encode("utf-8")
    if len(b) > MAX_BYTES:
        b = b[:MAX_BYTES]
        # try to avoid cutting inside a multibyte char; backtrack to a valid boundary
        try:
            b = b.decode("utf-8", errors="ignore").encode("utf-8")
        except Exception:
            # As a fallback, keep the already-sliced bytes
            pass

    return b
